                $fields=$kind==='service'?['title_fa'=>$first,'description_fa'=>$second]:($kind==='service_en'?['title_en'=>$first,'description_en'=>$second]:($kind==='team_profile'?['handle'=>$first,'bio'=>$second]:($kind==='team_contact'?['email'=>$first,'linkedin_url'=>$second]:['name'=>$first,'role'=>$second])));
